def search_distinct(T, M, iterations=1000):
    max_min_diff = 0
    for _ in range(iterations):
        # Generate a random subset of {0, ..., M} such that sum >= T
        # To make it more likely to have a large min_diff, let's pick values
        # that are spread out or have some property.
        n = random.randint(20, M+1)
        x = random.sample(range(M+1), n)
        if sum(x) >= T:
            max_min_diff = max(max_min_diff, get_min_diff(x, T))
    return max_min_diff

