def check_subset_sum(T, M):
    # We want to find a sequence x_i in {1, ..., M} such that sum(x) >= T
    # but no subset sum is exactly T.
    # This is like the Frobenius Coin Problem, but with a limited number of coins.
    # Let's try to find such a sequence.
    # If the min-diff is always 0, then d=0.

    # We can use DP to check if a sequence has a subset sum equal to T.
    def has_subset_sum(x, T):
        sums = {0}
        for val in x:
            new_sums = set()
            for s in sums:
                if s + val <= T:
                    new_sums.add(s + val)
            sums.update(new_sums)
            if T in sums:
                return True
        return False

    # Search for a counterexample
    for _ in range(10000):
        # Random sequence
        n = random.randint(T // M, T)
        x = [random.randint(1, M) for _ in range(n)]
        if sum(x) >= T:
            if not has_subset_sum(x, T):
                return x
    return None

