def check_hypothesis(T, M, iterations=10000):
    # Hypothesis: for any x_i in {1, ..., M} with sum(x) >= T,
    # there is a subset sum in [T-10, T].
    for _ in range(iterations):
        # To find a counterexample, we want to avoid [T-10, T]
        # Try different n values
        n = random.randint(T // M, T)
        x = [random.randint(1, M) for _ in range(n)]
        if sum(x) >= T:
            sums = {0}
            for val in x:
                new_sums = set()
                for s in sums:
                    if s + val <= T:
                        new_sums.add(s + val)
                sums.update(new_sums)
                if any(T-10 <= s <= T for s in sums):
                    break
            else:
                # No subset sum in [T-10, T]
                return x
    return None

